"""Builds docs/RESULTS_SUMMARY.md from results/*.json and injects it into README.md (between the SUMMARY markers).
Every number in the summary is read from the files the labs wrote - nothing is typed by hand."""
import json, os, pickle, sys
import numpy as np
ROOT = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, ROOT)
from rsi_lab.stats import paired_ci, load

def ci(a, b):
    m, lo, hi = paired_ci(a, b); return f"{m:+.3f} [{lo:+.3f}, {hi:+.3f}]"

def test_at(curve, spent):
    v = np.nan
    for s, _, t in curve:
        if s <= spent: v = t
        else: break
    return v

L = {k: load(f"lab_{k}.json") for k in ("10_03", "10_05", "10_06", "10_07", "10_10", "10_11", "10_13", "10_14", "10_15")}
R = L["10_03"]["res"]
logs = pickle.load(open(os.path.join(ROOT, "results", "so_rsi_logs.pkl"), "rb"))
def so(start, arm, b=8000): return np.array([test_at(l["curve"], b) for l in logs[start][arm]])
p, b_, s_ = so("planted", "naive"), so("planted", "naive+blind"), so("planted", "so_rsi")
c_n, c_b, c_s = so("clean", "naive"), so("clean", "naive+blind"), so("clean", "so_rsi")
h = L["10_14"]; h12, h6 = h["12000"], h["6000"]
a, sw, wf = L["10_10"], L["10_11"], L["10_13"]
m = lambda t: f"{t[0]:.3f}"
md = f"""All numbers: held-out accuracy on a 400-instance test split no method selects on; **30 fresh seeds (100-129)**; paired by seed; 95% bootstrap CIs.
Every method is charged in the same unit (instance evaluations). Generated by `make_summary.py` from `results/*.json`.

| Lab | Question | Result |
|---|---|---|
| 10.03 Budget RSI | Does the frozen linear readout beat a budget-matched Huxley-Goedel-style search? | readout {R['readout']['test_mean']:.3f}, parent-rate ablation {R['parent_rate']['test_mean']:.3f}, random {R['random']['test_mean']:.3f}, **HGM-matched {R['hgm_matched']['test_mean']:.3f}**, oracle {R['oracle']['test_mean']:.3f}. readout - HGM = {ci(R['readout']['tests'], R['hgm_matched']['tests'])}. Calibration = {100*L['10_03']['calibration_cost']/R['readout']['cost']:.0f}% of its cost. **Not reproduced here.** |
| 10.04/10.05 | Does the readout rank edits at all? | top-scored edit beats its parent {L['10_05']['A paper-8']['precision']:.0%} of the time vs {L['10_05']['A paper-8']['rand_precision']:.0%} random (mechanism works); canary feature: Spearman {L['10_05']['A paper-8']['rho']:.2f} -> {L['10_05']['B +canary']['rho']:.2f}; duplicate flag: no effect on wasted expansions. |
| 10.06 SO-RSI (planted blocker, budget 8000) | Does diagnose-then-fix beat first-order RSI? | naive {p.mean():.3f}, naive+blind-removal {b_.mean():.3f}, **SO-RSI {s_.mean():.3f}**. SO-RSI - naive = {ci(s_, p)}; **SO-RSI - naive+blind (fair baseline) = {ci(s_, b_)}**. Probes cost {100*L['10_07']['probe_cost']/8000:.0f}% of budget. |
| 10.06 SO-RSI (clean start) | Does it still help without the planted bug? | naive {c_n.mean():.3f}, naive+blind {c_b.mean():.3f}, SO-RSI {c_s.mean():.3f}; SO-RSI - naive+blind = {ci(c_s, c_b)} (loop creates its own blockers, so this is not a 'no structure' control). |
| 10.07 | Does the probe find the planted blocker? | named in {L['10_07']['planted_named']}/30 runs and fixed in {L['10_07']['planted_fixed']}/30; {100*L['10_07']['inconclusive_frac']:.0f}% of probes return no blocker; `opposing` anomalies never launched a probe. |
| 10.14 Self-HPO (budget 12000) | Does alternating harness+policy beat either alone? | none {m(h12['test']['none'])}, policy-only {m(h12['test']['policy_only'])}, harness-only {m(h12['test']['harness_only'])}, Self-HPO {m(h12['test']['self_hpo'])}; joint - none = {h12['joint_vs_none'][0]:+.3f} [{h12['joint_vs_none'][1]:+.3f}, {h12['joint_vs_none'][2]:+.3f}]; synergy = {h12['synergy'][0]:+.3f} [{h12['synergy'][1]:+.3f}, {h12['synergy'][2]:+.3f}] -> **not super-additive**. At budget 6000 the H-step used {100*h6['hstep_share']:.0f}% of the budget (Self-HPO {m(h6['test']['self_hpo'])} vs none {m(h6['test']['none'])}). |
| 10.10 AReaL-style | Does shared conditional memory beat independent researchers? | budget 2500: {a['2500']['shared'][0]:.3f} vs {a['2500']['indep'][0]:.3f}, diff {a['2500']['diff'][0]:+.3f} [{a['2500']['diff'][1]:+.3f}, {a['2500']['diff'][2]:+.3f}]; budget 4000: {a['4000']['diff'][0]:+.3f} [{a['4000']['diff'][1]:+.3f}, {a['4000']['diff'][2]:+.3f}] (no clear difference). |
| 10.11 Swarm-style | Does recombination help? | budget 6000: swarm {sw['6000']['test']['swarm'][0]:.3f}, mutation-only {sw['6000']['test']['mutation_only'][0]:.3f}, random {sw['6000']['test']['random'][0]:.3f}; diversity {sw['6000']['diversity_final']['swarm']:.2f} vs {sw['6000']['diversity_final']['mutation_only']:.2f}. Recombination adds nothing over mutation. |
| 10.13 RSIFlow-style | Does adaptive routing beat fixed workflows? | budget 6000: static {wf['6000']['static'][0]:.3f}, **all-on {wf['6000']['all_on'][0]:.3f}**, adaptive {wf['6000']['adaptive'][0]:.3f}. Adaptive > static, but all-on > adaptive (detection latency). |
| 10.15 RSI-Index | How much of the gap does each system close? | planted start: naive {L['10_15']['so:planted:naive'][0]:.2f}, naive+blind {L['10_15']['so:planted:naive+blind'][0]:.2f}, SO-RSI {L['10_15']['so:planted:so_rsi'][0]:.2f}; Self-HPO lab: none {L['10_15']['hpo:none'][0]:.2f}, Self-HPO {L['10_15']['hpo:self_hpo'][0]:.2f}. (Sign error in the course formula corrected.) |
"""
open(os.path.join(ROOT, "docs", "RESULTS_SUMMARY.md"), "w").write(md)
rd = open(os.path.join(ROOT, "README.md")).read()
a0, a1 = rd.index("<!--SUMMARY-->"), rd.index("<!--/SUMMARY-->")
open(os.path.join(ROOT, "README.md"), "w").write(rd[:a0] + "<!--SUMMARY-->\n" + md + rd[a1:])
print(md)
